87	  const explore = ExploreInput.safeParse(probe.input);
88	  if (explore.success) return runExplore(client(side), explore.data);
89	  const wide = WideInput.safeParse(probe.input);
90	  if (wide.success) return runWide(client(side), wide.data, toJson, errorJson);
91	  const life = LifeInput.safeParse(probe.input);
92	  if (life.success) return runLifecycle(client(side), life.data);
93	  const p = Input.parse(probe.input);
94	  const stripe = client(side);
95	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
96	  const price = async (plan: z.infer<typeof Plan>, name: string): Promise<string> => {
97	    const product = await stripe.products.create({ name });
98	    const created = await stripe.prices.create({
99	      product: product.id,
100	      currency: "usd",
101	      unit_amount: plan.amount,
102	      recurring: { interval: plan.interval },
103	    });
104	    return created.id;
105	  };
106	  const oldPrice = await price(p.plan, "Basic");
107	  const newPrice = p.change.plan ? await price(p.change.plan, "Pro") : null;
108	  const customer = await stripe.customers.create({
109	    test_clock: clock.id,
110	    payment_method: "pm_card_visa",
111	    invoice_settings: { default_payment_method: "pm_card_visa" },
112	    preferred_locales: ["en"],
113	  });
114	  const subscription = await stripe.subscriptions.create({
115	    customer: customer.id,
116	    items: [{ price: oldPrice, quantity: p.quantity }],
117	    billing_mode: { type: p.billing_mode },
118	    ...(p.coupon ? { discounts: [{ coupon: await couponId(stripe, p.coupon) }] } : {}),
119	  });
120	  const item = subscription.items.data[0];
121	  if (!item) throw new Error("subscription created without an item");
