129	        subscription_details: {
130	          items: [
131	            {
132	              id: item.id,
133	              ...(newPrice !== null ? { price: newPrice } : {}),
134	              ...(p.change.quantity !== null ? { quantity: p.change.quantity } : {}),
135	            },
136	          ],
137	          proration_date: p.start + p.change.offset,
138	          ...(p.change.proration_behavior !== null
