147	  }
148	  const first =
149	    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : null;
150	  const invoice = first !== null ? await stripe.invoices.retrieve(first) : null;
151	  return {
152	    preview,
153	    first_invoice: invoice
