67	async function waitReady(stripe: Stripe, clock: string): Promise<void> {
68	  for (let i = 0; i < 60; i += 1) {
69	    const c = await stripe.testHelpers.testClocks.retrieve(clock);
70	    if (c.status === "ready") return;
71	    await new Promise((r) => setTimeout(r, 1000));
72	  }
73	  throw new Error(`test clock ${clock} did not become ready`);
74	}
