76	export async function runLifecycle(
77	  stripe: Stripe,
78	  input: LifeInput,
79	): Promise<Record<string, Json>> {
80	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: input.start });
81	  const product = await stripe.products.create({ name: "Basic" });
82	  const price = await stripe.prices.create({
83	    product: product.id,
84	    currency: "usd",
85	    unit_amount: input.amount,
86	    recurring: { interval: "month" },
87	  });
88	  let price2: string | null = null;
89	  if (input.second_amount !== null) {
90	    const pro = await stripe.products.create({ name: "Pro" });
91	    price2 = (
92	      await stripe.prices.create({
93	        product: pro.id,
94	        currency: "usd",
95	        unit_amount: input.second_amount,
96	        recurring: { interval: "month" },
97	      })
98	    ).id;
99	  }
100	  const spare = input.spare_coupon !== null ? await couponId(stripe, input.spare_coupon) : null;
101	  const customer = await stripe.customers.create({
102	    test_clock: clock.id,
103	    payment_method: "pm_card_visa",
104	    invoice_settings: { default_payment_method: "pm_card_visa" },
105	    preferred_locales: ["en"],
106	  });
107	  const created = await stripe.subscriptions.create({
108	    customer: customer.id,
109	    items: [{ price: price.id }],
110	    ...(input.trial_days !== null ? { trial_period_days: input.trial_days } : {}),
111	    ...(input.coupon !== null
112	      ? { discounts: [{ coupon: await couponId(stripe, input.coupon) }] }
113	      : {}),
114	  });
115	  let now = input.start;
116	  const out: Record<string, Json> = {};
117	  for (const step of input.steps) {
118	    if (step.do === "cancel_at_period_end" || step.do === "reactivate") {
119	      await stripe.subscriptions.update(created.id, {
120	        cancel_at_period_end: step.do === "cancel_at_period_end",
121	      });
122	    } else if (step.do === "cancel_now") {
123	      await stripe.subscriptions.cancel(created.id, {
124	        prorate: step.prorate,
125	        invoice_now: step.invoice_now,
126	      });
127	    } else if (step.do === "advance") {
128	      now += step.seconds;
129	      await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: now });
130	      await waitReady(stripe, clock.id);
131	    } else if (step.do === "good_card") {
132	      const pm = await stripe.paymentMethods.attach("pm_card_visa", { customer: customer.id });
133	      await stripe.customers.update(customer.id, {
134	        invoice_settings: { default_payment_method: pm.id },
135	      });
136	    } else if (step.do === "failing_card") {
137	      const pm = await stripe.paymentMethods.attach("pm_card_chargeCustomerFail", {
138	        customer: customer.id,
139	      });
140	      await stripe.customers.update(customer.id, {
141	        invoice_settings: { default_payment_method: pm.id },
142	      });
143	    } else if (step.do === "raw") {
144	      const fill = (v: string): string =>
145	        v
146	          .replaceAll("{subscription}", created.id)
147	          .replaceAll("{customer}", customer.id)
148	          .replaceAll("{item}", created.items.data[0]?.id ?? "")
149	          .replaceAll("{price}", price.id)
150	          .replaceAll("{price2}", price2 ?? "")
151	          .replaceAll("{coupon}", spare ?? "");
152	      const params = Object.fromEntries(Object.entries(step.params).map(([k, v]) => [k, fill(v)]));
153	      try {
154	        // The SDK takes parameters on POST only; GET and DELETE carry them in the query string.
155	        const query = new URLSearchParams(params).toString();
156	        const body: unknown =
157	          step.method === "POST"
158	            ? await stripe.rawRequest("POST", fill(step.path), params)
159	            : await stripe.rawRequest(step.method, `${fill(step.path)}${query ? `?${query}` : ""}`);
160	        out[step.as] = { ok: true, body: JsonSchema.parse(JSON.parse(JSON.stringify(body))) };
161	      } catch (e) {
162	        if (!(e instanceof Stripe.errors.StripeError)) throw e;
163	        out[step.as] = {
164	          ok: false,
165	          error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
166	        };
167	      }
168	    } else if (step.do === "retrieve_missing") {
169	      try {
170	        await stripe.subscriptions.retrieve("sub_Missing0000000000");
171	        out[step.as] = { error: null };
172	      } catch (e) {
173	        if (!(e instanceof Stripe.errors.StripeError)) throw e;
174	        out[step.as] = {
175	          error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
176	        };
177	      }
178	    } else {
179	      const sub = await stripe.subscriptions.retrieve(created.id, { expand: ["latest_invoice"] });
180	      const item = sub.items.data[0];
181	      const latest = typeof sub.latest_invoice === "object" ? sub.latest_invoice : null;
182	      const invoices = await stripe.invoices.list({ subscription: sub.id, limit: 10 });
183	      out[step.as] = {
184	        status: sub.status,
185	        cancel_at_period_end: sub.cancel_at_period_end,
186	        cancel_at: sub.cancel_at ?? null,
187	        canceled_at: sub.canceled_at ?? null,
188	        ended_at: sub.ended_at ?? null,
189	        trial_end: sub.trial_end ?? null,
190	        period_start: item?.current_period_start ?? null,
191	        period_end: item?.current_period_end ?? null,
192	        latest_invoice: invoiceView(latest),
193	        invoice_count: invoices.data.length,
194	      };
195	    }
196	  }
197	  return out;
198	}
