51	export function str(v: Json | undefined): string | null {
52	  return typeof v === "string" ? v : typeof v === "number" ? String(v) : null;
53	}
54	export function num(v: Json | undefined): number | null {
55	  const s = str(v);
56	  if (s === null || s === "") return null;
57	  const n = Number(s);
58	  return Number.isFinite(n) ? n : null;
59	}
60	export function obj(v: Json | undefined): Params {
61	  return v !== null && typeof v === "object" && !Array.isArray(v) ? v : {};
62	}
63	export function arr(v: Json | undefined): Json[] {
64	  if (Array.isArray(v)) return v;
65	  if (v !== null && typeof v === "object") return Object.values(v);
66	  return [];
67	}
68	const bool = (v: Json | undefined): boolean => v === true || v === "true";
