70	function newDiscount(
71	  state: State,
72	  coupon: string,
73	  customer: string,
74	  sub: string | null,
75	  now: number,
76	): Discount {
77	  const d: Discount = {
78	    id: mint(state, "di"),
79	    coupon,
80	    customer,
81	    subscription: sub,
82	    start: now,
83	    used: false,
84	  };
85	  state.discounts[d.id] = d;
86	  return d;
87	}
