89	// pm_card_* tokens resolve to a new payment method each time.
90	function paymentMethodFrom(state: State, token: string, customer: string | null): string {
91	  if (get(state.payment_methods, token)) return token;
92	  const id = mint(state, "pm");
93	  state.payment_methods[id] = { id, customer, fails: token.includes("Fail") };
94	  return id;
95	}
