99	export function billFirstInvoice(state: State, sub: Subscription, now: number): Invoice {
100	  const id = mint(state, "in");
101	  const trial = sub.status === "trialing";
102	  const specs = trial ? [] : specsOf(state, sub.discounts);
103	  const lines: Line[] = sub.items.map((it) => {
104	    const p = priceOf(state, it.price);
105	    return {
106	      id: mint(state, "il"),
107	      amount: trial ? 0 : p.unit_amount * it.quantity,
108	      description: trial
109	        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
110	        : recurringDescription(state, it.price, it.quantity),
111	      period: { start: sub.period_start, end: sub.period_end },
112	      price: it.price,
113	      quantity: it.quantity,
114	      proration: false,
115	      discountable: true,
116	      discount_amounts: [],
117	      subscription_item: it.id,
118	      invoice_item: null,
119	      credited: null,
120	      unit_amount_decimal: String(p.unit_amount),
121	    };
122	  });
123	  const alloc = allocate(
124	    lines.map((l) => l.amount),
125	    specs,
126	  );
127	  lines.forEach((l, i) => {
128	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
129	  });
130	  sub.items.forEach((it, i) => {
131	    const l = lines[i];
132	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
133	  });
134	  spendOnce(state, specs, alloc);
135	  const tda = specs.map((s, k) => ({
136	    discount: s.id,
137	    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
138	  }));
139	  const inv: Invoice = {
140	    id,
141	    customer: sub.customer,
142	    subscription: sub.id,
143	    lines,
144	    discounts: specs.map((s) => s.id),
145	    total_discount_amounts: tda,
146	    billing_reason: "subscription_create",
147	    status: "paid",
148	    created: now,
149	    period_start: now,
150	    period_end: now,
151	    attempt_count: 0,
152	    amount_paid: 0,
153	    auto_advance: false,
154	    next_payment_attempt: null,
155	    proration_date: null,
156	    retries: [],
157	    starting_balance: 0,
158	    deferred: 0,
159	  };
160	  if (!deferSmall(state, inv)) {
161	    const due = amountDue(inv);
162	    inv.amount_paid = due;
163	    inv.attempt_count = due > 0 ? 1 : 0;
164	  }
165	  state.invoices[id] = inv;
166	  sub.latest_invoice = id;
167	  return inv;
168	}
