172	function createSubscription(state: State, p: Params): CloneResponse {
173	  const customerId = str(p.customer) ?? "";
174	  const customer = get(state.customers, customerId);
175	  if (!customer) return missing("customer", customerId);
176	  const now = nowFor(state, customerId);
177	  const id = mint(state, "sub");
178	  const items = arr(p.items).map((raw) => {
179	    const it = obj(raw);
180	    return {
181	      id: mint(state, "si"),
182	      price: str(it.price) ?? "",
183	      quantity: num(it.quantity) ?? 1,
184	      created: now,
185	      billed: null,
186	    };
187	  });
188	  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
189	  const first = items[0];
190	  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
191	  const trialDays = num(p.trial_period_days);
192	  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
193	  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
194	  const sub: Subscription = {
195	    id,
196	    customer: customerId,
197	    items,
198	    billing_mode: mode,
199	    discounts: [],
200	    anchor: trialEnd ?? now,
201	    period_start: now,
202	    period_end: trialEnd ?? addIntervals(now, interval, 1),
203	    status: trialEnd !== null ? "trialing" : "active",
204	    created: now,
205	    latest_invoice: null,
206	    cancel_at_period_end: false,
207	    cancel_at: null,
208	    canceled_at: null,
209	    ended_at: null,
210	    trial_start: trialEnd !== null ? now : null,
211	    trial_end: trialEnd,
212	  };
213	  for (const raw of arr(p.discounts)) {
214	    const coupon = str(obj(raw).coupon) ?? "";
215	    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
216	    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
217	  }
218	  state.subscriptions[id] = sub;
219	  billFirstInvoice(state, sub, now);
220	  return ok(subscriptionJson(state, sub, false));
221	}
