223	function previewInvoice(state: State, p: Params): CloneResponse {
224	  const subId = str(p.subscription) ?? "";
225	  const sub = get(state.subscriptions, subId);
226	  if (!sub) return missing("subscription", subId);
227	  const details = obj(p.subscription_details);
228	  const changes: ItemChange[] = arr(details.items).map((raw) => {
229	    const it = obj(raw);
230	    return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
231	  });
232	  const now = nowFor(state, sub.customer);
233	  const discounts =
234	    p.discounts !== undefined
235	      ? arr(p.discounts).map(
236	          (raw) => newDiscount(state, str(obj(raw).coupon) ?? "", sub.customer, null, now).id,
237	        )
238	      : null;
239	  const behavior = str(details.proration_behavior) as Behavior | null;
240	  const plan = planChange(state, sub, {
241	    changes,
242	    proration_date: num(details.proration_date),
243	    behavior,
244	    discounts,
245	    now,
246	  });
247	  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
248	  const draft = draftFromPlan(
249	    state,
250	    sub,
251	    plan,
252	    { line: () => mint(state, "il_tmp"), item: () => mint(state, "ii") },
253	    sub.billing_mode,
254	  );
255	  const inv: Invoice = {
256	    id: mint(state, "upcoming_in"),
257	    customer: sub.customer,
258	    subscription: sub.id,
259	    lines: draft.lines,
260	    discounts: draft.discounts,
261	    total_discount_amounts: draft.total_discount_amounts,
262	    billing_reason: "upcoming",
263	    status: "draft",
264	    created: draft.created,
265	    period_start: draft.period_start,
266	    period_end: draft.period_end,
267	    attempt_count: 0,
268	    amount_paid: 0,
269	    auto_advance: !draft.immediate,
270	    next_payment_attempt: draft.immediate ? null : draft.created + 3600,
271	    proration_date: plan.proration_date,
272	    retries: [],
273	    starting_balance: get(state.customers, sub.customer)?.balance ?? 0,
274	    deferred: 0,
275	  };
276	  return ok(invoiceJson(state, inv, true));
277	}
