279	function updateSubscription(state: State, sub: Subscription, p: Params): CloneResponse {
280	  const now = nowFor(state, sub.customer);
281	  if (p.cancel_at_period_end !== undefined) {
282	    const on = bool(p.cancel_at_period_end);
283	    sub.cancel_at_period_end = on;
284	    sub.cancel_at = on ? sub.period_end : null;
285	    sub.canceled_at = on ? now : null;
286	  }
287	  return ok(subscriptionJson(state, sub, false));
288	}
