290	function listInvoices(state: State, q: Params): CloneResponse {
291	  const sub = str(q.subscription);
292	  const limit = num(q.limit) ?? 10;
293	  const all = Object.values(state.invoices)
294	    .filter((i) => sub === null || i.subscription === sub)
295	    .reverse()
296	    .slice(0, limit);
297	  return ok({
298	    object: "list",
299	    data: all.map((i) => invoiceJson(state, i, false)),
300	    has_more: false,
301	    url: "/v1/invoices",
302	  });
303	}
304	
305	function listInvoiceItems(state: State, q: Params): CloneResponse {
306	  const customer = str(q.customer);
307	  const pending = bool(q.pending);
308	  const items = Object.values(state.invoice_items)
309	    .filter((i) => customer === null || i.customer === customer)
310	    .filter((i) => !pending || i.invoice === null)
311	    .reverse();
312	  return ok({
313	    object: "list",
314	    data: items.map((i) => ({
315	      id: i.id,
316	      object: "invoiceitem",
317	      amount: i.line.amount,
318	      customer: i.customer,
319	      description: i.line.description,
320	      invoice: i.invoice,
321	      period: { start: i.line.period.start, end: i.line.period.end },
322	      proration: i.line.proration,
323	      quantity: i.line.quantity,
324	    })),
325	    has_more: false,
326	    url: "/v1/invoiceitems",
327	  });
328	}
