330	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
331	  const parts = req.path.split("/").filter((s) => s !== "");
332	  if (parts[0] !== "v1") return null;
333	  const [, a, b, c, d] = parts;
334	  const m = req.method;
335	
336	  if (a === "test_helpers" && b === "test_clocks") {
337	    if (m === "POST" && c === undefined) {
338	      const id = mint(state, "clock");
339	      const t = num(p.frozen_time) ?? 0;
340	      state.clocks[id] = { id, frozen_time: t, created: t };
341	      return ok(clockJson(state, id));
342	    }
343	    const clock = c !== undefined ? get(state.clocks, c) : undefined;
344	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
345	    if (m === "GET") return ok(clockJson(state, c));
346	    if (m === "POST" && d === "advance") {
347	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
348	      return ok(clockJson(state, c));
349	    }
350	  }
351	  if (a === "products" && m === "POST" && b === undefined) {
352	    const id = mint(state, "prod");
353	    state.products[id] = { id, name: str(p.name) ?? "" };
354	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
355	  }
356	  if (a === "prices" && m === "POST" && b === undefined) {
357	    const id = mint(state, "price");
358	    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
359	    state.prices[id] = {
360	      id,
361	      product: str(p.product) ?? "",
362	      unit_amount: num(p.unit_amount) ?? 0,
363	      currency: str(p.currency) ?? "usd",
364	      interval,
365	    };
366	    return ok(priceJson(state, id));
367	  }
368	  if (a === "coupons" && m === "POST" && b === undefined) {
369	    const id = mint(state, "coupon");
370	    const coupon = {
371	      id,
372	      percent_off: num(p.percent_off),
373	      amount_off: num(p.amount_off),
374	      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
375	    };
376	    state.coupons[id] = coupon;
377	    return ok(couponJson(coupon));
378	  }
379	  if (a === "customers") {
380	    if (m === "POST" && b === undefined) {
381	      const id = mint(state, "cus");
382	      const clock = str(p.test_clock);
383	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
384	      const pmToken = str(p.payment_method);
385	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
386	      state.customers[id] = { id, clock, default_payment_method: pm, created: now, balance: 0 };
387	      return ok({
388	        id,
389	        object: "customer",
390	        test_clock: clock,
391	        invoice_settings: { default_payment_method: pm },
392	      });
393	    }
394	    const cus = b !== undefined ? get(state.customers, b) : undefined;
395	    if (!cus || b === undefined) return missing("customer", b ?? "");
396	    if (m === "POST" && c === undefined) {
397	      const dpm = str(obj(p.invoice_settings).default_payment_method);
398	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
399	    }
400	    return ok({
401	      id: cus.id,
402	      object: "customer",
403	      test_clock: cus.clock,
404	      invoice_settings: { default_payment_method: cus.default_payment_method },
405	    });
406	  }
407	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
408	    const id = paymentMethodFrom(state, b, str(p.customer));
409	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
410	  }
411	  if (a === "subscriptions") {
412	    if (m === "POST" && b === undefined) return createSubscription(state, p);
413	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
414	    if (!sub || b === undefined) return missing("subscription", b ?? "");
415	    if (m === "GET") {
416	      const expand = arr(p.expand).map(str);
417	      return ok(subscriptionJson(state, sub, expand.includes("latest_invoice")));
418	    }
419	    if (m === "DELETE") {
420	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
421	      return ok(subscriptionJson(state, sub, false));
422	    }
423	    if (m === "POST") return updateSubscription(state, sub, p);
424	  }
425	  if (a === "invoices") {
426	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
427	    if (m === "GET" && b === undefined) return listInvoices(state, p);
428	    if (m === "GET" && b !== undefined) {
429	      const inv = get(state.invoices, b);
430	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
431	    }
432	  }
433	  if (a === "invoiceitems" && m === "GET" && b === undefined) return listInvoiceItems(state, p);
434	  return null;
435	}
436	
437	function clockJson(state: State, id: string): Json {
438	  const c = get(state.clocks, id);
439	  return {
440	    id,
441	    object: "test_helpers.test_clock",
442	    created: c?.created ?? 0,
443	    frozen_time: c?.frozen_time ?? 0,
444	    livemode: false,
445	    status: "ready",
446	  };
447	}
