195	const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
196	
197	// Deterministic IDs: the same calls after a reset mint the same IDs.
198	export function mint(state: State, prefix: string): string {
199	  state.n += 1;
200	  const n = state.n;
201	  let x = n * 7919 + 104729;
202	  let s = "";
203	  while (s.length < 14) {
204	    s = (ALPHABET[x % 62] ?? "0") + s;
205	    x = Math.floor(x / 62) + n * 31;
206	  }
207	  // Stripe IDs start with an upper-case letter or digit after the prefix; keep one fixed shape.
208	  return `${prefix}_1${s}`;
209	}
210	
211	export function get<T>(table: Record<string, T>, id: string): T | undefined {
212	  return Object.hasOwn(table, id) ? table[id] : undefined;
213	}
214	
215	// The clock time a customer lives on (its test clock), or the subscription's creation time.
216	export function nowFor(state: State, customer: string): number {
217	  const c = get(state.customers, customer);
218	  const clock = c?.clock ? get(state.clocks, c.clock) : undefined;
219	  return clock ? clock.frozen_time : Math.floor(Date.now() / 1000);
220	}
