1	/**
2	 * Time on a test clock: renewals at the period end, payment attempts an hour later, retries of a
3	 * failed payment, the end of a subscription set to cancel, and cancelling now (LIF-*).
4	 */
5	import {
6	  allocate,
7	  spendOnce,
8	  amountDue,
9	  creditLine,
10	  deferSmall,
11	  priceOf,
12	  recurringDescription,
13	  specOf,
14	  specsOf,
15	} from "./billing.ts";
16	import {
17	  get,
18	  mint,
19	  nowFor,
20	  type Clock,
21	  type Invoice,
22	  type Line,
23	  type State,
24	  type Subscription,
25	} from "./state.ts";
26	import { periodAt } from "./time.ts";
27	
28	const HOUR = 3600;
29	const DAY = 86400;
30	// Retries after a failed renewal payment, counted from the first attempt (LIF-06). Pinned by
31	// dev-v2-retry-days: the first retry within 2 days, the second after 3 days 1 hour and by 4 days
32	// 1 hour; l-payment-fails-retries: no fourth attempt by 5 days. 1 and 4 days fit both.
33	const RETRIES = [1 * DAY, 4 * DAY];
34	
35	function failing(state: State, customer: string): boolean {
36	  const c = get(state.customers, customer);
37	  const pm = c?.default_payment_method
38	    ? get(state.payment_methods, c.default_payment_method)
39	    : undefined;
40	  return pm?.fails === true;
41	}
42	
43	export function invoiceTotal(inv: Invoice): number {
44	  const sub = inv.lines.reduce((a, l) => a + l.amount, 0);
45	  return sub - inv.total_discount_amounts.reduce((a, d) => a + d.amount, 0);
46	}
47	
48	// Pending invoice items (prorations) of a subscription, moved onto an invoice.
49	export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
50	  const out: Line[] = [];
51	  for (const ii of Object.values(state.invoice_items)) {
52	    if (ii.subscription !== sub.id || ii.invoice !== null) continue;
53	    ii.invoice = invoice;
54	    out.push({ ...ii.line, id: mint(state, "il") });
55	  }
56	  return out;
57	}
58	
59	function renew(state: State, sub: Subscription): void {
60	  const start = sub.period_end;
61	  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
62	  const end = periodAt(sub.anchor, interval, start)[1];
63	  const id = mint(state, "in");
64	  const pending = takePending(state, sub, id);
65	  const lines: Line[] = sub.items.map((it) => {
66	    const p = priceOf(state, it.price);
67	    return {
68	      id: mint(state, "il"),
69	      amount: p.unit_amount * it.quantity,
70	      description: recurringDescription(state, it.price, it.quantity),
71	      period: { start, end },
72	      price: it.price,
73	      quantity: it.quantity,
74	      proration: false,
75	      discountable: true,
76	      discount_amounts: [],
77	      subscription_item: it.id,
78	      invoice_item: null,
79	      credited: null,
80	      unit_amount_decimal: String(p.unit_amount),
81	    };
82	  });
83	  const active = sub.discounts.filter((d) => {
84	    const s = specOf(state, d);
85	    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
86	  });
87	  const specs = specsOf(state, active);
88	  const alloc = allocate(
89	    lines.map((l) => l.amount),
90	    specs,
91	  );
92	  lines.forEach((l, i) => {
93	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
94	  });
95	  spendOnce(state, specs, alloc);
96	  sub.items.forEach((it, i) => {
97	    const l = lines[i];
98	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
99	  });
100	  const all = [...pending, ...lines];
101	  const inv: Invoice = {
102	    id,
103	    customer: sub.customer,
104	    subscription: sub.id,
105	    lines: all,
106	    discounts: specs.map((s) => s.id),
107	    total_discount_amounts: specs.map((s, k) => ({
108	      discount: s.id,
109	      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
110	    })),
111	    billing_reason: "subscription_cycle",
112	    status: "draft",
113	    created: start,
114	    period_start: sub.period_start,
115	    period_end: start,
116	    attempt_count: 0,
117	    amount_paid: 0,
118	    auto_advance: true,
119	    next_payment_attempt: start + HOUR,
120	    proration_date: null,
121	    retries: [],
122	    starting_balance: 0,
123	    deferred: 0,
124	  };
125	  // The customer balance moves onto the renewal invoice; a credit beyond its total stays.
126	  const cus = get(state.customers, sub.customer);
127	  if (cus) {
128	    inv.starting_balance = cus.balance;
129	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
130	  }
131	  state.invoices[id] = inv;
132	  sub.latest_invoice = id;
133	  sub.period_start = start;
134	  sub.period_end = end;
135	  if (sub.status === "trialing") sub.status = "active";
136	}
137	
138	function attempt(state: State, inv: Invoice, at: number): void {
139	  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
140	  const due = amountDue(inv);
141	  if (due === 0 || deferSmall(state, inv)) {
142	    inv.status = "paid";
143	    inv.next_payment_attempt = null;
144	    return;
145	  }
146	  inv.attempt_count += 1;
147	  if (!failing(state, inv.customer)) {
148	    inv.status = "paid";
149	    inv.amount_paid = due;
150	    inv.next_payment_attempt = null;
151	    if (sub?.status === "past_due") sub.status = "active";
152	    return;
153	  }
154	  inv.status = "open";
155	  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
156	  const next = inv.retries.shift();
157	  inv.next_payment_attempt = next ?? null;
158	  if (sub && sub.status !== "canceled") sub.status = "past_due";
159	}
160	
161	// Runs every event of the clock's customers up to `to`, in time order.
162	export function advanceClock(state: State, clock: Clock, to: number): void {
163	  const customers = new Set(
164	    Object.values(state.customers)
165	      .filter((c) => c.clock === clock.id)
166	      .map((c) => c.id),
167	  );
168	  for (let guard = 0; guard < 1000; guard += 1) {
169	    const events: { at: number; run: () => void }[] = [];
170	    const consider = (at: number, run: () => void): void => {
171	      if (at <= to) events.push({ at, run });
172	    };
173	    for (const sub of Object.values(state.subscriptions)) {
174	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
175	      const cancelAt = sub.cancel_at;
176	      if (cancelAt !== null && cancelAt <= sub.period_end) {
177	        consider(cancelAt, () => {
178	          sub.status = "canceled";
179	          sub.ended_at = cancelAt;
180	        });
181	        continue;
182	      }
183	      consider(sub.period_end, () => {
184	        if (sub.cancel_at_period_end) {
185	          sub.status = "canceled";
186	          sub.ended_at = sub.period_end;
187	        } else {
188	          renew(state, sub);
189	        }
190	      });
191	    }
192	    for (const inv of Object.values(state.invoices)) {
193	      if (!customers.has(inv.customer)) continue;
194	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
195	        const at = inv.next_payment_attempt;
196	        if (at !== null) {
197	          consider(at, () => {
198	            attempt(state, inv, at);
199	          });
200	        }
201	      }
202	    }
203	    // The earliest event first; ties keep discovery order (subscriptions before invoices).
204	    const chosen = events.reduce<{ at: number; run: () => void } | null>(
205	      (best, e) => (best === null || e.at < best.at ? e : best),
206	      null,
207	    );
208	    if (chosen === null) break;
209	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
210	    chosen.run();
211	  }
212	  clock.frozen_time = to;
213	}
214	
215	export function cancelNow(
216	  state: State,
217	  sub: Subscription,
218	  prorate: boolean,
219	  invoiceNow: boolean,
220	): void {
221	  const now = nowFor(state, sub.customer);
222	  if (prorate && now < sub.period_end) {
223	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
224	    if (invoiceNow) {
225	      const id = mint(state, "in");
226	      const pending = takePending(state, sub, id);
227	      const lines: Line[] = [
228	        ...pending,
229	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
230	      ];
231	      state.invoices[id] = {
232	        id,
233	        customer: sub.customer,
234	        subscription: sub.id,
235	        lines,
236	        discounts: [],
237	        total_discount_amounts: [],
238	        billing_reason: "subscription_cycle",
239	        status: "draft",
240	        created: now,
241	        period_start: sub.period_start,
242	        period_end: now,
243	        attempt_count: 0,
244	        amount_paid: 0,
245	        auto_advance: false,
246	        next_payment_attempt: null,
247	        proration_date: null,
248	        retries: [],
249	        starting_balance: 0,
250	        deferred: 0,
251	      };
252	      sub.latest_invoice = id;
253	    } else {
254	      for (const l of credits) {
255	        const id = mint(state, "ii");
256	        state.invoice_items[id] = {
257	          id,
258	          customer: sub.customer,
259	          subscription: sub.id,
260	          line: { ...l, id: "", invoice_item: id },
261	          invoice: null,
262	        };
263	      }
264	    }
265	  }
266	  sub.status = "canceled";
267	  sub.ended_at = now;
268	  sub.canceled_at ??= now;
269	  sub.cancel_at_period_end = false;
270	  sub.cancel_at = null;
271	}
