1	/**
2	 * The billing engine: discount allocation, proration arithmetic, and the plan of a subscription
3	 * change (which lines it bills, now or at the next renewal). Pure functions over the state; the
4	 * API layer turns their output into Stripe objects.
5	 */
6	import {
7	  get,
8	  type Billed,
9	  type Coupon,
10	  type DiscountAmount,
11	  type Invoice,
12	  type Line,
13	  type State,
14	  type SubItem,
15	  type Subscription,
16	} from "./state.ts";
17	import { addIntervals, money, periodAt, shortDate, type Interval } from "./time.ts";
18	
19	// ---------------------------------------------------------------- rounding
20	
21	// round(num / den) half away from zero, on exact integers (den > 0).
22	export function roundRatio(num: number, den: number): number {
23	  const sign = num < 0 ? -1 : 1;
24	  const a = Math.abs(num);
25	  return sign * Math.floor((2 * a + den) / (2 * den));
26	}
27	
28	// Percent with up to four decimals, as an exact integer fraction of 1 000 000.
29	const PPM = 1_000_000;
30	const ppm = (percent: number): number => Math.round(percent * 10_000);
31	
32	// ---------------------------------------------------------------- discounts
33	
34	export interface DiscSpec {
35	  id: string;
36	  percent_off: number | null;
37	  amount_off: number | null;
38	  once: boolean;
39	}
40	
41	export function specOf(state: State, discountId: string): DiscSpec | undefined {
42	  const d = get(state.discounts, discountId);
43	  const c = d ? get(state.coupons, d.coupon) : undefined;
44	  if (!d || !c) return undefined;
45	  return {
46	    id: d.id,
47	    percent_off: c.percent_off,
48	    amount_off: c.amount_off,
49	    once: c.duration === "once",
50	  };
51	}
52	
53	export function specsOf(state: State, ids: string[]): DiscSpec[] {
54	  return ids.map((id) => specOf(state, id)).filter((s): s is DiscSpec => s !== undefined);
55	}
56	
57	// Discounts apply one after another; each is spread over the discountable lines in proportion to
58	// what is left of them, with the rounding remainder on the last line. Result: [discount][line].
59	export function allocate(bases: number[], discounts: DiscSpec[]): number[][] {
60	  const left = bases.map((b) => Math.max(0, b));
61	  return discounts.map((d) => {
62	    const sum = left.reduce((a, b) => a + b, 0);
63	    const out = left.map(() => 0);
64	    if (sum <= 0) return out;
65	    // A percent-off takes round(pct x sum) and spreads it like an amount-off (DSC-01).
66	    const total =
67	      d.percent_off !== null
68	        ? roundRatio(sum * ppm(d.percent_off), PPM)
69	        : Math.min(d.amount_off ?? 0, sum);
70	    // Cumulative flooring: line i gets floor(T C_i / S) - floor(T C_(i-1) / S), C_i the running
71	    // sum of the bases (pass 5; "one cent from the last line" is its 2- and 3-line case).
72	    const T = BigInt(total);
73	    const S = BigInt(sum);
74	    let cum = 0n;
75	    let prev = 0n;
76	    left.forEach((b, i) => {
77	      cum += BigInt(b);
78	      const upTo = (T * cum) / S;
79	      out[i] = Number(upTo - prev);
80	      prev = upTo;
81	    });
82	    left.forEach((b, i) => {
83	      left[i] = b - (out[i] ?? 0);
84	    });
85	    return out;
86	  });
87	}
88	
89	// A once coupon is spent by the first invoice where it took more than 0 (pass 5): one that got
90	// nothing stays active for the next invoice.
91	export function spendOnce(state: State, specs: DiscSpec[], alloc: number[][]): void {
92	  specs.forEach((s, k) => {
93	    const d = get(state.discounts, s.id);
94	    const took = (alloc[k] ?? []).reduce((a, b) => a + b, 0);
95	    if (d && s.once && took > 0) d.used = true;
96	  });
97	}
98	
99	export function couponLabel(c: Pick<Coupon, "percent_off" | "amount_off">): string {
100	  if (c.percent_off !== null) {
101	    const p = c.percent_off;
102	    return `${Number.isInteger(p * 10) ? p.toFixed(1) : String(p)}% off`;
103	  }
104	  return `${money(c.amount_off ?? 0)} off`;
105	}
106	
107	function withDiscounts(specs: DiscSpec[]): string {
108	  if (specs.length === 0) return "";
109	  if (specs.length > 1) return " (with discounts)";
110	  const [s] = specs;
111	  return s ? ` (with ${couponLabel(s)})` : "";
112	}
113	
114	// ---------------------------------------------------------------- lines
115	
116	export function priceOf(state: State, id: string) {
117	  const p = get(state.prices, id);
118	  if (!p) throw new Error(`unknown price ${id}`);
119	  return p;
120	}
121	
122	export function productName(state: State, priceId: string): string {
123	  const p = priceOf(state, priceId);
124	  return get(state.products, p.product)?.name ?? "";
125	}
126	
127	export function recurringDescription(state: State, priceId: string, quantity: number): string {
128	  const p = priceOf(state, priceId);
129	  return `${quantity} × ${productName(state, priceId)} (at ${money(p.unit_amount)} / ${p.interval})`;
130	}
131	
132	const qtyPrefix = (q: number): string => (q > 1 ? `${q} × ` : "");
133	
134	export function intervalOf(state: State, sub: Subscription): Interval {
135	  const first = sub.items[0];
136	  return first ? priceOf(state, first.price).interval : "month";
137	}
138	
139	// ---------------------------------------------------------------- change plan
140	
141	export interface ItemChange {
142	  id: string;
143	  price: string | null;
144	  quantity: number | null;
145	}
146	
147	export type Behavior = "create_prorations" | "none" | "always_invoice";
148	
149	export interface PlannedItem {
150	  id: string;
151	  price: string;
152	  quantity: number;
153	}
154	
155	export interface Plan {
156	  // Proration lines, without IDs.
157	  prorations: Omit<Line, "id" | "invoice_item">[];
158	  // The discounts each proration line actually carries (for its discount list).
159	  own: DiscSpec[][];
160	  // Per proration line: how many discounts a credit line carried (null for a charge).
161	  carried: (number | null)[];
162	  items: PlannedItem[];
163	  // Per planned item: its interval and the end of its current (possibly new) period.
164	  intervals: Interval[];
165	  ends: number[];
166	  // Items whose price or quantity changes.
167	  changed: string[];
168	  // Discounts of the new state (a once coupon passed to the preview included).
169	  discounts: string[];
170	  // Once coupons that took something from the remaining-time charges (spent there).
171	  spent: string[];
172	  immediate: boolean;
173	  // A classic interval change restarts the cycle at the clock time.
174	  reset: boolean;
175	  period_start: number;
176	  // When the preview invoice falls: the earliest item period end (or the reset period's end).
177	  period_end: number;
178	  anchor: number;
179	  proration_date: number;
180	  now: number;
181	}
182	
183	export interface PlanError {
184	  message: string;
185	  param: string | null;
186	}
187	
188	export interface PlanInput {
189	  changes: ItemChange[];
190	  proration_date: number | null;
191	  behavior: Behavior | null;
192	  // Discount IDs replacing the subscription's, or null to keep them.
193	  discounts: string[] | null;
194	  now: number;
195	}
196	
197	interface Carried {
198	  spec: DiscSpec;
199	  amount: number;
200	}
201	
202	// Every discount on the line that billed the period, those it got nothing from included.
203	function billedDiscounts(state: State, billed: Billed | null): Carried[] {
204	  if (!billed) return [];
205	  return billed.discounts
206	    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
207	    .filter((x): x is Carried => x.spec !== undefined);
208	}
209	
210	// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
211	// item got on the invoice that billed the period (PRO-01, DSC-04).
212	export function creditLine(
213	  state: State,
214	  sub: Subscription,
215	  it: SubItem,
216	  prd: number,
217	): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[]; carried: number } {
218	  const oldPrice = priceOf(state, it.price);
219	  const P = sub.period_end - sub.period_start;
220	  const r = sub.period_end - prd;
221	  const b = oldPrice.unit_amount * it.quantity;
222	  const all = billedDiscounts(state, it.billed);
223	  const carried = all.filter((c) => c.amount !== 0);
224	  let credit: number;
225	  let applied: DiscSpec[];
226	  if (sub.billing_mode === "classic") {
227	    // Classic: the coupons apply to the credited item on its own (an amount-off coupon in full,
228	    // not its share of a multi-item invoice), then the net amount is prorated. The label names
229	    // every discount of the billed line, zero ones included (pass 5).
230	    const D = allocate(
231	      [b],
232	      carried.map((c) => c.spec),
233	    ).reduce((a, x) => a + (x[0] ?? 0), 0);
234	    credit = -roundRatio((b - D) * r, P);
235	    applied = all.map((c) => c.spec);
236	  } else {
237	    // Flexible: a carried discount whose prorated amount rounds to 0 is not applied (DSC-08).
238	    const prorated = carried.map((c) => roundRatio(c.amount * r, P));
239	    credit = -(roundRatio(b * r, P) - prorated.reduce((a, x) => a + x, 0));
240	    applied = carried.filter((_, k) => (prorated[k] ?? 0) !== 0).map((c) => c.spec);
241	  }
242	  return {
243	    line: {
244	      amount: credit,
245	      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
246	      period: { start: prd, end: sub.period_end },
247	      price: it.price,
248	      quantity: it.quantity,
249	      proration: true,
250	      discountable: false,
251	      discount_amounts: [],
252	      subscription_item: it.id,
253	      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
254	      unit_amount_decimal: null,
255	    },
256	    own: applied,
257	    // Discounts on the billed line, those it got nothing from included (DSC-07).
258	    carried: all.length,
259	  };
260	}
261	
262	// Classic charge: r/P truncated to a fixed number of decimals, times the amount, half up
263	// (pass 5: 99999999 x 1/18 = 5555555.5 is charged 5555555, 3000 x 0.0075 = 22.5 is charged 23).
264	const CLASSIC_DIGITS = 10n ** 12n;
265	function classicProrate(n: number, r: number, P: number): number {
266	  const f = (BigInt(r) * CLASSIC_DIGITS) / BigInt(P);
267	  const x = BigInt(n) * f;
268	  const sign = x < 0n ? -1n : 1n;
269	  const a = x < 0n ? -x : x;
270	  return Number(sign * ((2n * a + CLASSIC_DIGITS) / (2n * CLASSIC_DIGITS)));
271	}
272	
273	const SAME_INTERVAL =
274	  "All prices on a subscription must have the same `recurring.interval` and `recurring.interval_count` unless flexible billing mode is enabled and you're on the 2025-06-30.basil API version or later. To proceed, update the subscription to flexible billing mode, then retry this update. For information about flexible billing mode, go to https://docs.stripe.com/billing/subscriptions/billing-mode. ";
275	const MIXED_COUPONS =
276	  "Subscriptions with multiple intervals only support percent_off coupons, `duration=once` amount_off coupons, and `duration=repeating` amount_off coupons.";
277	
278	export function planChange(state: State, sub: Subscription, input: PlanInput): Plan | PlanError {
279	  const behavior = input.behavior ?? "create_prorations";
280	  if (behavior === "none" && input.proration_date !== null) {
281	    return {
282	      message: "Cannot specify proration date if no proration is being done",
283	      param: "proration_date",
284	    };
285	  }
286	  const prd = input.proration_date ?? input.now;
287	  if (prd < sub.period_start || prd > sub.period_end) {
288	    return {
289	      message: `Cannot specify proration date outside of current subscription period or current phase. The value should be between ${sub.period_start} and ${sub.period_end}.`,
290	      param: "proration_date",
291	    };
292	  }
293	  const items: PlannedItem[] = sub.items.map((it) => {
294	    const ch = input.changes.find((c) => c.id === it.id);
295	    if (!ch) return { id: it.id, price: it.price, quantity: it.quantity };
296	    const priceChanged = ch.price !== null && ch.price !== it.price;
