558	// The smallest amount the account charges (INV-01): dev-t2-f-left55 is not charged, left56 is.
559	export const MIN_CHARGE = 56;
560	
561	// What an invoice asks for: its total plus the starting balance, less an amount deferred to the
562	// customer balance because it was below the minimum charge.
563	export function amountDue(inv: {
564	  lines: Line[];
565	  total_discount_amounts: DiscountAmount[];
566	  starting_balance: number;
567	  deferred: number;
568	}): number {
569	  const { total } = totals(inv.lines, inv.total_discount_amounts);
570	  return Math.max(0, total + inv.starting_balance) - inv.deferred;
571	}
572	
573	// Charges below the minimum are not attempted: the amount goes to the customer balance.
574	export function deferSmall(state: State, inv: Invoice): boolean {
575	  const due = amountDue(inv);
576	  if (due <= 0 || due >= MIN_CHARGE) return false;
577	  inv.deferred += due;
578	  const c = get(state.customers, inv.customer);
579	  if (c) c.balance += due;
580	  inv.status = "paid";
581	  inv.next_payment_attempt = null;
582	  return true;
583	}
