585	export function totals(lines: Line[], tda: DiscountAmount[]) {
586	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
587	  const discount = tda.reduce((a, d) => a + d.amount, 0);
588	  return { subtotal, total: subtotal - discount };
589	}
