// Local replay of chosen dev cases against the clone (scratch tool, not part of the repo).
import { readFileSync } from "node:fs";
import { startCloneProcess } from "/work/harness/src/clone-process.ts";
import { PolicySchema, diff, blocking } from "/work/harness/src/policy.ts";
import adapter from "/work/targets/stripe-billing/adapter.ts";

const dir = "/work/targets/stripe-billing/fixtures/dev/";
const policy = PolicySchema.parse(
  JSON.parse(readFileSync("/work/targets/stripe-billing/policy.json", "utf8")),
);
const ids = process.argv.slice(2);
const port = 4700 + Math.floor(Math.random() * 200);
const clone = await startCloneProcess("stripe-billing", "clone/server.ts", port);
let pass = 0;
for (const id of ids) {
  const f = JSON.parse(readFileSync(`${dir}${id}.json`, "utf8"));
  await fetch(`http://127.0.0.1:${port}/__reset`, { method: "POST" });
  const actual = await adapter.run(
    { id, input: f.input } as never,
    { kind: "clone", url: `http://127.0.0.1:${port}` } as never,
  );
  const pol = {
    ...policy,
    fields: [
      ...policy.fields,
      ...(f.noise as string[]).map((path) => ({ path, mode: "ignore" as const, why: "noise" })),
    ],
  };
  const d = blocking(diff(pol, f.observed, actual));
  if (d.length === 0) pass++;
  console.log(`${d.length === 0 ? "PASS" : "FAIL"} ${id} ${d.length}`);
  for (const x of d.slice(0, Number(process.env.N ?? 12)))
    console.log(`  ${x.path}: ${JSON.stringify(x.expected)} => ${JSON.stringify(x.actual)}`);
}
console.log(`${pass}/${ids.length}`);
await clone.stop();
process.exit(0);

